import asyncio
from async_bridge import run_sync


def run_with_deadline(coros: list, seconds: float) -> list:
    """Run coroutines concurrently from synchronous code, returning results in input order.
    Any coroutine not finishing within `seconds` is cancelled and its result replaced by None.
    Works when called repeatedly in the same process."""
    async def _run_all_with_deadline(coros, timeout):
        tasks = [asyncio.create_task(c) for c in coros]
        done, pending = await asyncio.wait(tasks, timeout=timeout)
        # Cancel any pending tasks
        for task in pending:
            task.cancel()
        # Wait for cancellations to complete
        if pending:
            await asyncio.gather(*pending, return_exceptions=True)
        results = []
        for task in tasks:
            if task in done:
                try:
                    results.append(task.result())
                except Exception:
                    # Propagate exceptions from finished tasks
                    raise
            else:
                # Timed out tasks replaced by None
                results.append(None)
        return results

    return run_sync(_run_all_with_deadline(coros, seconds))

