        done, pending = await asyncio.wait(tasks, timeout=seconds)
        # Cancel pending tasks
        for task in pending:
            task.cancel()
        # Await cancellation completion to suppress warnings
        await asyncio.gather(*pending, return_exceptions=True)
        results = []
        for task in tasks:
            if task in done:
                try:
                    results.append(task.result())
                except Exception:
                    # If a task raised, propagate exception
                    raise
            else:
                results.append(None)
        return results

    try:
        loop = asyncio.get_running_loop()
    except RuntimeError:
        # no running loop
        return asyncio.run(_run_all_with_deadline())
    else:
        # running loop: run coro in a new task and wait for it synchronously
        # This is a rare case; run_with_deadline is documented for no running loop.
        # We create a new task and wait for it with a new event loop in a thread.
        # But to keep it simple and safe, raise RuntimeError here.
        raise RuntimeError("run_with_deadline() cannot be called from a running event loop")

