        done, pending = await asyncio.wait(tasks, timeout=seconds)
        # Cancel pending tasks
        for task in pending:
            task.cancel()
        # Await cancellation completion
        for task in pending:
            try:
                await task
            except asyncio.CancelledError:
                pass
        # Collect results in input order, None for cancelled or errored tasks
        results = []
        for task in tasks:
            if task in done:
                try:
                    results.append(task.result())
                except Exception:
                    results.append(None)
            else:
                results.append(None)
        return results

    return run_sync(_run_all_with_deadline())
